quests[35819] = { id = 35819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy of Glory: Khargax the Devourer", description = "Defeating Khargax has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", completion = "The Laughing Skull have always steered clear of that area because Khargax was very quick for such a huge beast. They will be pleased to know their eaten dead have been avenged.", objectives = "Take the trophy to Durotan at Beastwatch in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35820] = { id = 35820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy of Glory: Khargax the Devourer", description = "Defeating Khargax has yielded you a trophy worthy of showing off at your outpost. \n\nReturn this to Maraad to increase your glory!", completion = "You have done us all a great favor {name}.\n\nThe existence of that slippery hydra wasn't even truly known despite our losses in the area.", objectives = "Take the trophy to Maraad at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35821] = { id = 35821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy of Glory: Sodius", description = "Defeating Erosian has yielded you a trophy worthy of showing off at your gladiatorial arena. \n\nReturn this to <ARENA NPC NAME> to increase your glory!", sourceObjective = "Take the trophy to <ARENA NPC NAME> at <HORDE OUTPOST> in Gorgrond.", sourceObjectiveStatus = "unverified-source-field" }
quests[35822] = { id = 35822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy of Glory: Sodius", description = "Defeating Sodius has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at <HORDE OUTPOST>.", sourceObjective = "Take the trophy to Durotan at <HORDE OUTPOST> in Gorgrond.", sourceObjectiveStatus = "unverified-source-field" }
quests[35823] = { id = 35823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparkling Band", progress = "Every little bit counts.", completion = "Often forgotten as armor, rings can often make all the difference in a battle. Their magic is subtle but significant. I will be sure to make sure these make it to the battlefront." }
