quests[35825] = { id = 35825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imbued Locket", progress = "Every little bit counts.", completion = "This locket still has some magic left in it, I am sure we could out fit a few of our soldiers, even those that think jewelry doesn't suit them." }
