quests[35827] = { id = 35827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Focused Crystal", progress = "Every little bit counts.", completion = "Ooh, shiny. I think I can put this crystal to good use in a couple of projects I am working on." }
quests[35828] = { id = 35828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Drew Aggro...culture", completion = "Ah perfect. I'll get this up an' runnin' in no time.", objectives = "Meet Thaelin Darkanvil at the Wildwood Wash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35829] = { id = 35829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buffed Crystal", progress = "Every little bit counts.", completion = "Ooh, shiny. I think I can put this crystal to good use in a couple of projects I am working on." }
quests[35830] = { id = 35830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immaculate Statue", progress = "Every little bit counts.", completion = "Statues were once a staple of combat on Azeroth, this statue will definitely be put to good use." }
quests[35831] = { id = 35831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restored Statue", progress = "Every little bit counts.", completion = "Statues were once a staple of combat on Azeroth, this statue will definitely be put to good use." }
quests[35832] = { id = 35832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priceless Gryphon Figurine" }
quests[35833] = { id = 35833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crude Gryphon Figurine", progress = "Every little bit counts.", completion = "Some claim figurines bring luck on a battlefield. In truth most figurines are imbued with magical properties by craftsman with the gift. It looks like you have a touch of the gift, the soldiers here will prize this." }
quests[35834] = { id = 35834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wake of the Genesaur", description = "One moment we see a great metal beast rolling into our camp, the next a genesaur follows it and sends a wave of pure chaotic life at us.\n\nThe manifestations left behind by the genesaur must be culled so we have time to salvage what we can before leaving.\n\nIf you are here to help, then start killing as many of the violent plants that are assailing us as possible.", completion = "A good start. The growth from a genesaur is pure chaos and must be culled whenever possible.", objectives = "Slay 9 Wild Overgrowth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35835] = { id = 35835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ebon Hunter", description = "We're ready to set up the laser, but we're going to need more firepower to cut through this stuff.\n\nThe Ebon Hunter stalks the delta just southeast from here. It has an apparatus on its face that can fire a laser way stronger than what we have hooked up.\n\nWe need that.\n\nYou should go get it while we set up the laser.", progress = "By the way, that laser is very dangerous. Be careful!", completion = "Alright, let's put this thing to use!", objectives = "Collect an Organic Laser Apparatus from the Ebon Hunter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35836] = { id = 35836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 008 - The Lunker" }
quests[35837] = { id = 35837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: Deep Recon", description = "One of my top field operatives, Jeanine Amrell, is stationed deep in Iron Horde territory in northern Nagrand.\n\nShe reports that the warlords of the orcish clans are planning to convene in secret at Mok'gol Watchpost.\n\nThis may be a critical opportunity for us to gain intel on their future plans.\n\nI need you to meet up with agent Amrell immediately. This may be our chance, {name}!", completion = "<Judging by the marks on her body, the agent put up an impressive fight.>", objectives = "Find Jeanine Amrell at the Hidden Camp in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35838] = { id = 35838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warlord's Council", description = "Upon closer inspection, you notice a piece of leather parchment looped around her neck.\n\nScrawled upon it angrily are the words:\n\n\"WITNESS THE FATE OF THOSE WHO DEFY THE IRON HORDE!\"", completion = "I'm glad I found you, {name}. I've been hiding out since the Warsong orcs ambushed our camp at the Hidden Camp.\n\nYou should have seen the fight that Jeanine put up. Even after they began torturing her, she never gave up that there were two of us.\n\nShe had a will of steel, that one.", objectives = "Find out who is behind the written note.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35839] = { id = 35839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plans of War", description = "I managed to get my hands on Jeanine's notebook. She identified several key items in the nearby buildings to investigate, but couldn't follow up before her demise.\n\nThe least we can do is follow the lead that she left us.\n\nSearch the camp for the intelligence. I'll keep the orcs distracted.", completion = "This is remarkable, {name}. We now have direct proof of Grommash's intentions.\n\nPerhaps now, we can stay a step ahead of the Iron Horde. Great work!", objectives = "Find the Scale Model of Gorgorek, Miniature War Machine, and Map of Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35840] = { id = 35840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intercepting the Orders", description = "Intelligence is the name of the game, friend. The more we know about Hellscream's plans, the easier it will be to thwart them.\n\nThe Mok'gol orcs often act as Hellscream's couriers, carrying mission orders from this place to his outposts all over Draenor.\n\nKill these riders, and recover any orders that you can find.", progress = "Do you have something for me?", completion = "Excellent work, {name}.", objectives = "Collect the Frostfire Mission Orders, Shadowmoon Mission Orders, and Spires of Arak Mission Orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35841] = { id = 35841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting Down the Packleader", description = "Operations at Mok'gol Watchpost are entrusted to a mighty warrior named Packleader Vor'gash.\n\nIf we can take out this fierce leader, we can shut down their communications temporarily.\n\nYou can find Vor'gash patrolling the compound to the northeast.\n\nSlay him.", completion = "I have heard many reports about Vor'gash. It is a relief to know he will trouble us no more.", objectives = "Slay Packleader Vor'gash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35842] = { id = 35842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting Down the Packleader", description = "Da one in charge a Mok'gol Watchpost be Packleader Vor'gash.\n\nWe take him out, we shut dem down.\n\nYa ken find 'im patrolling da compound ta da nor'east.\n\nKill 'im.", completion = "I know about dis Vor'gash. It be a relief ta know he won't trouble us no more.", objectives = "Slay Packleader Vor'gash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35843] = { id = 35843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: Deep Recon", description = "Ya timin' be good, commanda.\n\nI sent one a ma shadow huntas deep inta da land 'a da enemy.\n\nHe reports dat da warlords be plannin' ta meet in secret at Mok'gol Watchpost.\n\nDis be our chance ta learn what Hellscream be up to.\n\nGo now, and meet wit Zasta. He will tell ya what to do next.", completion = "<Judging by the marks on his body, the shadow hunter put up an impressive fight.>", objectives = "Find Shadow Hunter Zasta at the Hidden Camp in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35844] = { id = 35844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warlord's Council", description = "Upon closer inspection, you notice a piece of leather parchment looped around his neck.\n\nScrawled upon it angrily are the words:\n\n\"WITNESS THE FATE OF THOSE WHO DEFY THE IRON HORDE!\"", completion = "I ben lookin' for ya, commanda. I knew you was comin', but dat nasty orc lady got ta ya afore I could give warnin'.\n\nAt least I could save ya. Poor Zasta. He never saw it comin'.", objectives = "Find out who is behind the written note.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35845] = { id = 35845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plans of War", description = "I managed ta recover Zasta's notes. He saw dey Warsong leaders meetin' often in dey nearby buildings. Zasta tinks dere be clues about dey Iron Horde's plans nearby.\n\nDey least we can do is follow dey lead he left us.\n\nSearch dey camp for dey intelligence. I'll keep dey orcs distracted.", completion = "Now we have proof a Hellscream's intentions.\n\nMebbe now, we ken stay a step ahead a da Iron Horde. Gud work.", objectives = "Find the Scale Model of Gorgorek, Miniature War Machine, and Map of Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35846] = { id = 35846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intercepting the Orders", description = "Intelligence be da name a da game, commanda. Da more we know about Hellscream's plans, da easier it be ta mess dem.\n\nDa Mok'gol orcs be Hellscream's couriers, carrying mission orders from dis place ta his outposts all over Draenor.\n\nKill dese riders, an' recover any orders dat you ken find.", progress = "Ya have something for me?", completion = "Dis is gud, {name}. Dis be real gud.", objectives = "Collect the Frostfire Mission Orders, Shadowmoon Mission Orders, and Spires of Arak Mission Orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35847] = { id = 35847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Voidseer Kalurg" }
quests[35848] = { id = 35848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Medic Kit", progress = "Every little bit counts.", completion = "We've been short on medical supplies ever since we landed in Draenor. This fresh kit can help us keep up with the demand." }
quests[35849] = { id = 35849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Medic Kit", progress = "Every little bit counts.", completion = "We've been short on medical supplies ever since we landed in Draenor. This fresh kit can help us keep up with the demand." }
quests[35850] = { id = 35850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protective Medic Vest", progress = "Every little bit counts.", completion = "Now the field medics will have more protection when treating wounds in the field. I will place this in their stockpile." }
quests[35851] = { id = 35851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Medic Vestments", progress = "Every little bit counts.", completion = "Now the field medics will have more protection when treating wounds in the field. I will place this in their stockpile." }
quests[35852] = { id = 35852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Antivenom Kit", progress = "Every little bit counts.", completion = "This seems like a safer way to save a life or limb from poison. I'll make sure to distribute this out right away!" }
quests[35853] = { id = 35853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Immunoglobulin Kit", progress = "Every little bit counts.", completion = "With all of the strange diseases in Draenor, we need to boost our immune systems as much as we can. I'll make sure to distribute this out right away!" }
quests[35854] = { id = 35854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botanic Cure Guide", progress = "Every little bit counts.", completion = "We have needed a more reliable guide for the herbs in this area. Now we can create safer healing salves that will actually work!" }
