quests[35856] = { id = 35856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standard Survey Bot", progress = "Every little bit counts.", completion = "The expedition scout will be thrilled to see their survey bot again. She assumed it was lost in action after the party was ambushed. I will make sure it is returned to her when she comes back from their mission." }
quests[35857] = { id = 35857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turbo Survey Bot", progress = "Every little bit counts.", completion = "The expedition scout will be thrilled to see their survey bot again. She assumed it was lost in action after the party was ambushed. I will make sure it is returned to her when she comes back from their mission." }
quests[35858] = { id = 35858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precision-Tuned Scope", progress = "Every little bit counts.", completion = "This will aid our hunters well in tracking large game and enemy units. We will put this to use right away." }
quests[35859] = { id = 35859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyper Sight Scope", progress = "Every little bit counts.", completion = "This will aid our hunters well in tracking large game and enemy units. We will put this to use right away." }
quests[35860] = { id = 35860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackrock Fragment Grenade", progress = "Every little bit counts.", completion = "The engineers will agree that you can never have enough grenades. This extra shipment will make them happy." }
quests[35861] = { id = 35861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: Darktide Roost", description = "We are getting reports that Iron Horde warships are docking on a small island just south of Shadowmoon Valley.\n\nWe sent in some scouts, but we haven't heard back from them yet. It might be worth investigating.\n\nDungar Longdrink has a gryphon waiting for you when you are ready, commander.", completion = "These savages have no honor, it is time we deal with the Iron Horde presence on this island.", objectives = "Travel to Darktide Roost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35862] = { id = 35862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackrock Cluster Bomb", progress = "Every little bit counts.", completion = "This seems like a great explosive to deter any large enemy from attacking us. I'm sure the engineers will be thrilled to see this in our stockpile." }
quests[35863] = { id = 35863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proximity Alarm Bot", progress = "Every little bit counts.", completion = "We've been short on Alarm Bots since the last attack. We will put this to use right away." }
