quests[35868] = { id = 35868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bunch of Artifact Fragments", progress = "The more, the better!", completion = "That must of taken great effort to get back to us. You deserve this reward, friend." }
quests[35869] = { id = 35869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A TON of Artifact Fragments", progress = "As much as you can carry.", completion = "Great work, {class}! I will let Vindicator Maraad know of your bravery." }
quests[35870] = { id = 35870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basilisk Butcher", description = "Basilisk is one of Nisha's favorite meals. This is where she hunts, and that's likely how those Iron Horde bastards were able to capture her.\n\nWhy would they go to the trouble to subdue her this way? Perhaps together, you and I might learn the answer as we punish them for their transgressions.\n\nFor now, Nisha's going to need some food. While I tend to her, will you do her hunting for her?", progress = "<Nisha sniffs deeply.>", completion = "<Nisha downs the meat in one gulp.>", objectives = "Collect 9 Basilisk Meat from Stoneshamble Basilisks or Decaying Basilisks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35871] = { id = 35871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Few Artifact Fragments", progress = "Every little bit counts.", completion = "Every little bit helps." }
