quests[35875] = { id = 35875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 024 - Ophiis" }
quests[35876] = { id = 35876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: Darktide Roost", description = "We is getting reports dat da Iron Horde warships be dockin' on a small island to da south of da Shadowmoon Valley.\n\nWe be sendin' some scouts, but we haven't heard back yet. We need ta be investigating.\n\nBron Skyhorn has a ryklak waitin' for ya when you be ready, commander.", completion = "These savages have no honor, it is time we deal with the Iron Horde presence on this island.", objectives = "Travel to Darktide Roost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35877] = { id = 35877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 005 - Windcaller Korast" }
quests[35878] = { id = 35878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety Measures", description = "As it turns out, the resonance frequency of the batteries has really upset the local wildlife. I... I think one of the boars looked at me and licked its lips just a moment ago.\n\nI'll make it worth your time if you just... get rid of anything you come across down there. Doesn't matter what it is, just kill it, okay?", completion = "Fantastic! This is some good old-fashioned adventuring if I've ever seen it.", objectives = "Kill 15 bog denizens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35879] = { id = 35879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety Measures", description = "The batteries I lost in the bog have really ticked off the wild creatures. It's going to be impossible to remove them without fighting through who knows what.\n\nIf you're up for it, why don't you 'take care' of any critters you come across? I don't want some giant beast stalking me back to the excavation site.\n\nI'll make it worth your while.", completion = "Now that's what I'm talking about. You're tough as nails.", objectives = "Kill 15 bog denizens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35880] = { id = 35880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rage and Wisdom", description = "Beasts of the western wasteland fight an endless war with the creatures of the eastern wilds.\n\nIf one side were to overwhelm the other, all of Draenor would be doomed at the hand of the victor.\n\nThe Laughing Skull seek revenge for their destroyed village. I have directed them to aim their vengeance at the nearby creatures, that our outpost here might be preserved.\n\nIf you would, commander, oversee their efforts. I have not yet grown to trust the Laughing Skull.", completion = "I can see the future of my enemies in the bones. They're gonna die!", objectives = "Speak to Bony Xuk at Affliction Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35881] = { id = 35881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruins of the First Bastion" }
quests[35882] = { id = 35882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Interest of Bruto", description = "You have done me a great service. This blade is as much yours as it is mine.\n\nI offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces.\n\nWill you accept it?", completion = "Now THAT is how you break out of a gladiator pit!\n\nYou are fun. Your weapons are covered in a rainbow of blood types.\n\nI am going to follow you now.", objectives = "Accept the Blood Oath of Blademaster Na'Shra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35883] = { id = 35883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fists of Vaandaam", description = "You have done me a great service. This blade is as much yours as it is mine.\n\nI offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces.\n\nWill you accept it?", completion = "For years the ogres would make me fight, kill, and salute. My soul bled with each salute.\n\nBut because of you, I will never again have to salute an ogre.\n\nYou have helped me win my freedom, so I choose to use that freedom to serve your banner.\n\nToday, I salute you, commander.", objectives = "Accept the Blood Oath of Blademaster Na'Shra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35884] = { id = 35884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Home Stretch", description = "If they weren't angry before, they sure are now. We won't survive a minute up on top o' this tank!\n\nLet's join up with the rest and get out of here!!", completion = "Against all odds, here we stand. Still alive, an entire army on our heels.\n\nOur ship is waiting. Shall we depart?", objectives = "Escape to the docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35885] = { id = 35885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maraudon (Wicked Grotto) Reward Quest" }
