quests[35903] = { id = 35903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackrock Depths (Detention Bonus) Reward Quest" }
quests[35904] = { id = 35904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackrock Depths (Everything) Reward Quest" }
quests[35905] = { id = 35905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supply Drop", description = "Your laborers below have finished with the harvest and are ready to cart supplies back to your garrison. Don't worry about the safety of your caravan this time; I will dispatch a rangari detail to shadow them from the woods and protect them.\n\nThe Exarchs will always watch over you.\n\nYour supplies should be waiting for you when you return to your garrison. Good luck with your campaign, {name}!", completion = "Commander! Zipfizzle arrived with your laborers in tow just moments ago. We've got a huge surplus of food, now, and promises of more where that came from.\n\nApparently the draenei threw in some other resources as well. Very good work, sir. What should we build next?", objectives = "Speak with Baros Alexston at your garrison in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35906] = { id = 35906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Mad \"King\" Sporeon" }
quests[35907] = { id = 35907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attempted Murder", description = "Your bartender Lunzul is dying, commander. She's been poisoned and needs an antidote immediately.\n\nOne of your scouts reported seeing a Shattered Hand orc nearby recently - that's our best bet.\n\nThere is a small arakkoa camp to the east that sits near a known Shattered Hand encampment. I suggest we start our search there.\n\nI've already spoken to your flight master about securing us a flight; every second counts.", completion = "These corpses are fresh. Their killers must still be nearby.", objectives = "Speak to Hutou Featherwind to secure a flight to Shadow's Vigil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35908] = { id = 35908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Stoneshard Broodmother" }
quests[35909] = { id = 35909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Insha'tar" }
quests[35910] = { id = 35910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Stomper Kreego" }
