quests[35959] = { id = 35959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Poison", description = "G.V.? We need a full name. A  location!\n\nI have an idea fer how we can find those out.\n\n<Hulda pulls out a small vial.>\n\nThis is my last vial o' wracking poison. We use it when we need tae extract information from prisoners.\n\nCoat yer weapon wi' it and head into the Shattered Hand camp just ahead. Engage them as normal and demand answers - the poison will take care o' the rest.", completion = "Gardul Venomshiv, eh? He's good as dead.", objectives = "Interrogate Shattered Hand orcs in the Harvesting Pits to find out the name and location of \"G.V.\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
