quests[35969] = { id = 35969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 018 - Adventurer's Pack" }
quests[35970] = { id = 35970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preservation Capitalization", description = "I'm looking for precious artifacts. The kind of artifacts that can help solve some of the greatest mysteries of Draenor, and make the Steamwheedle Preservation Society a ton of moolah. And ladies love the moolah, know what I'm sayin?\n\nSo, get me the artifacts, I'll get the ladies, and you get... wait, what are you looking for again?", progress = "What do you find? Anything worth selling? Err.. preserving.", completion = "Nice! What did you get?\n\nA necklace, not bad.. another necklace, good. A giant rock in the shape of an ogre head?\n\n<Greblin seems puzzled, he glances up at you.>\n\nSeriously? This is a rock in the shape of an idiot. Whatever, the necklaces look good.\n\nNot a bad find overall.", objectives = "Collect a Redtooth Necklace, Purpletooth Necklace, and an Ogre Bust.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35971] = { id = 35971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 7" }
quests[35972] = { id = 35972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Onslaught", description = "Those ogres are standing in the way of a full Steamwheedle Preservation excavation.\n\nThey are brutal, violent, horrible smelling beasts. And if I'm being completely honest with myself, I'm pretty mad they broke my glider.\n\nDo me a favor will ya? Wipe 'em off the face of Draenor.\n\nIt will make everyone's life easier, or at the very least, it will make my life easier.", completion = "Oh, that's way better.\n\nMaybe next time they'll think twice before they throw a rock at someone. Err... I mean if they weren't so dead and everything.", objectives = "Kill 3 Ogres and 3 Ogron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35973] = { id = 35973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brokyo Beatdown", description = "I'm almost done here, but I can't leave in good conscience.\n\nI spotted an ogron named Brokyo that is wearing a priceless ring. Priceless as in crazy expensive.\n\nI'm sure Nixxie will give me a promotion if I bring that ring back to her.", progress = "Did you take care of Brokyo?", completion = "You got the ring? Nice! The Steamwheedle Preservation Society is going to make some serious moolah on this stuff.\n\nNixxie will be pleased.", objectives = "Kill Brokyo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35974] = { id = 35974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Darktide Roost", description = "The Iron Horde has Goblins now? Take them out!", objectives = "Disrupt the Iron Horde and gather intelligence on them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
