quests[36075] = { id = 36075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Ogron Horn", description = "This horn is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the horn back to Jonaa and claim your accolades!", completion = "It is hard to admit that there is a creature more brutal than an ogre, but the ogron definitely fit that description. Facing a captured ogron in the arena is no mean feat. Facing one in their own lair is something even more dangerous. Hail to thee champion!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36076] = { id = 36076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Ogron Horn", description = "This horn is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the horn back to Limbflayer and claim your accolades!", completion = "There is a creature more brutal than an ogre. Facing a captured ogron in the arena is no mean feat. Facing one in their own lair is something even more dangerous. I like your style.", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36077] = { id = 36077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 063 - Adventurer's Mace" }
quests[36078] = { id = 36078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Gronnling Scale", description = "This scale is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the scale back to Jonaa and claim your accolades!", completion = "A gladiator saw you tear this off the back of a gronnling, which I am sure did not part with it easily. It is more like a stone than a true scale though as these brutes are part stone it seems. Not an easy trophy to collect!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36079] = { id = 36079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Welcome", description = "You have arrived in Frostfire Ridge. Farseer Drek'Thar can guide you from here.", sourceObjective = "Speak with Farseer Drek'Thar at Glacier Bay in Frostfire Ridge.", sourceObjectiveStatus = "unverified-source-field" }
